/**
  * Set up the copy-on-write diff file for this connection
  *
  * Copy-on-write exports never write to the master file; instead, all
  * written data goes into a per-connection diff file, which is removed
  * again when the client disconnects. This function computes the name
  * of that diff file (either in the same directory as the master file
  * or in the directory named by the cowdir option), creates it, and
  * allocates the map telling us, for every page of the export, whether
  * it is present in the diff file and, if so, where.
  *
  * @param client the CLIENT structure with .server set up correctly and
  * the export opened, so that the export size is known
  * @return true on success, false on failure
  */
static bool copyonwrite_prepare(CLIENT* client) {
	off_t i;
	_cleanup_g_free_ gchar* dir = NULL;
	_cleanup_g_free_ gchar* export_base = NULL;
	if (client->server->cowdir != NULL) {
		dir = g_strdup(client->server->cowdir);
	} else {
		dir = g_strdup(dirname(client->exportname));
	}
	export_base = g_strdup(basename(client->exportname));
	client->difffilename = g_strdup_printf("%s/%s-%s-%d.diff",dir,export_base,client->clientname,
		(int)getpid());
	msg(LOG_INFO, "About to create map and diff file %s", client->difffilename) ;
	client->difffile=open(client->difffilename,O_RDWR | O_CREAT | O_TRUNC,0600) ;
	if (client->difffile<0) {
		err("Could not create diff file (%m)");
		return false;
	}
	if ((client->difmap=calloc(client->exportsize/DIFFPAGESIZE,sizeof(uint32_t)))==NULL) {
		err("Could not allocate memory");
		return false;
	}
	for (i=0;i<client->exportsize/DIFFPAGESIZE;i++) client->difmap[i]=(uint32_t)-1;

	return true;
}

