/**
 * Read an amount of bytes at a given offset from the right file. This
 * abstracts the read-side of the copyonwrite stuff: for pages that
 * have been written during this connection, the data is read from the
 * diff file, and calls rawexpread_fully() for the master file
 * otherwise.
 * @param ctx The read context
 * @param client The client we're going to read for
 * @return 0 on success, nonzero on failure
 **/
int expread(READ_CTX *ctx, CLIENT *client) {
	off_t rdlen, offset;
	off_t mapcnt, mapl, maph, pagestart;
	off_t a = (off_t)ctx->current_offset + (off_t)ctx->req->from;
	size_t len = (size_t) ctx->req->len;
	int rv = 0;

	DEBUG("Asked to read %u bytes at %llu.\n", (unsigned int)len, (unsigned long long)a);

	if (!(client->server->flags & F_COPYONWRITE))
		return(rawexpread_fully(ctx, client));

	mapl=a/DIFFPAGESIZE; maph=(a+len-1)/DIFFPAGESIZE;

	for (mapcnt=mapl;mapcnt<=maph;mapcnt++) {
		pagestart=mapcnt*DIFFPAGESIZE;
		offset=a-pagestart;
		rdlen=(0<DIFFPAGESIZE-offset && len<(size_t)(DIFFPAGESIZE-offset)) ?
			len : (size_t)DIFFPAGESIZE-offset;
		if (client->difmap[mapcnt]!=(uint32_t)(-1)) { /* the block is already there */
			DEBUG("Page %llu is at %lu\n", (unsigned long long)mapcnt,
			       (unsigned long)(client->difmap[mapcnt]));
			char *buf = find_read_buf(ctx);
			if (pread(client->difffile, buf, rdlen, (off_t)client->difmap[mapcnt]*DIFFPAGESIZE+offset) != rdlen) {
				goto fail;
			}
			ctx->current_offset += rdlen;
			confirm_read(client, ctx, rdlen);
		} else { /* the block is not there */
			DEBUG("Page %llu is not here, we read the original one\n",
			       (unsigned long long)mapcnt);
			ctx->current_len = rdlen;
			if(rawexpread_fully(ctx, client)) goto fail;
		}
		len-=rdlen; a+=rdlen;
	}
	rv = 0;
	goto end;
fail:
	rv = -1;
end:
	return rv;
}

